import{_ as t,c as a,o as r,ah as n}from"./chunks/framework.DOavZf3W.js";const p=JSON.parse(`{"title":"Baker's Percentage","description":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios.","frontmatter":{"title":"Baker's Percentage","description":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios.","head":[["meta",{"name":"description","content":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios."}],["meta",{"property":"og:title","content":"Baker's Percentage"}],["meta",{"property":"og:description","content":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/bakers-percentage.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Baker's Percentage"}],["meta",{"name":"twitter:description","content":"Learn how to calculate baker's percentages to scale recipes and understand dough hydration and ingredient ratios."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/bakers-percentage.html"}]]},"headers":[],"relativePath":"guides/bakers-percentage.md","filePath":"guides/bakers-percentage.md"}`),o={name:"guides/bakers-percentage.md"};function s(i,e,l,c,h,d){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="baker-s-percentage" tabindex="-1">Baker&#39;s Percentage <a class="header-anchor" href="#baker-s-percentage" aria-label="Permalink to “Baker&#39;s Percentage”">​</a></h1><p>Baker’s percentage is the baker’s shorthand for ratios. Flour is the yardstick, everything else is measured against it. That makes scaling clean and predictable.</p><ul><li>Flour is always <strong>100%</strong>.</li><li>Water, yeast, salt, and enrichments are percentages of the flour weight.</li></ul><h2 id="the-big-aha-it-won-t-add-up-to-100" tabindex="-1">The Big “Aha”: It Won’t Add Up to 100% <a class="header-anchor" href="#the-big-aha-it-won-t-add-up-to-100" aria-label="Permalink to “The Big “Aha”: It Won’t Add Up to 100%”">​</a></h2><p>This trips people up at first. In baker’s math, <strong>100% is just the flour</strong>, not the total dough.<br> So if you add 65% water + 2% salt + 1% yeast, you get <strong>168% total</strong>. That is normal.<br> Think of the percentages as <strong>relative to flour</strong>, not a pie chart of the whole dough.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><p>For a dough with:</p><ul><li>500g flour</li><li>325g water</li><li>10g salt</li><li>5g yeast</li></ul><p>The baker’s percentages are:</p><ul><li>Water: 325 ÷ 500 × 100 = <strong>65%</strong></li><li>Salt: 10 ÷ 500 × 100 = <strong>2%</strong></li><li>Yeast: 5 ÷ 500 × 100 = <strong>1%</strong></li></ul><h2 id="why-bakers-love-it" tabindex="-1">Why Bakers Love It <a class="header-anchor" href="#why-bakers-love-it" aria-label="Permalink to “Why Bakers Love It”">​</a></h2><ul><li><strong>Scale fast</strong>: set the ratio, change the flour, everything follows.</li><li><strong>Compare recipes</strong>: two doughs can be compared by their percentages, not their batch size.</li><li><strong>Tune with intent</strong>: change hydration or salt by a point or two and you’ll feel it.</li></ul>',12)])])}const u=t(o,[["render",s]]);export{p as __pageData,u as default};
